head.script:
scwin.dpoTotCnt = function() {
    var json = dataList1.getMatchedJSON("LNDEP_DVCD", "1"); //수신
    var rtnval = json.length;
    return rtnval;
}
scwin.dpoTotAmt = function() {
    var json = dataList1.getMatchedJSON("LNDEP_DVCD", "1"); //수신
    var rtnval = 0;
    for (var i = 0; i < json.length; i++) {
        rtnval = rtnval + Math.abs(json[i].LDG_BALAMT);
    }
    return rtnval;
}
