scwin.dpoFmlSubCnt = function(val) {
    var json = dataList23.getMatchedJSON("CSNO", val);
    var rtnval = 0;
    for (var i = 0; i < json.length; i++) {
        if (json[i].LNDEP_DVCD == "1") { //수신
            rtnval++;
        }
    }
    return rtnval;
}
