scwin.setLinkFormat = function(data, fdata, row, col) {
    var strIsucoCd = dataList2.getCellData(row, "ISUCO_CD");
    var strBancaPdCd = dataList2.getCellData(row, "BANCA_PD_CD");
    if (!comUtil.isNull(strIsucoCd) && !comUtil.isNull(strBancaPdCd)) {
        fdata = "" + fdata + "";
    }
    return fdata;
}
scwin.search = function() {
    comUtil.openScreen("INP0303030310", "");
}
