    selCNTRCTSTC.setReadOnly(true);
    selCNTRCTSTC.setValue("1");
    mFun.searchInfo = function() {
        if (ciobCommon.notInqCust()) {
            return;
        }
        dataMap1.setJSON(comInqMap.getJSON());
        dataMap1.set("FML_CUST_INCL_YN", selFmlCustInclYn.getValue());
        dataMap1.set("INQ_DVCD", selInqDvcd.getValue());
        window.trans = new TransClass();
        // 거래전 활성탭에 따라 가져올 데이터 설정해주기				
        window.div = tabControl2.getSelectedTabIndex();
        if (div == null || div == "") {
            div = "0";
        }
        trans.div = div;
        dataMap1.set("TRNS_DVCD", div);
        //거래 로그에 사유 입력 부분 설정
        trans.inqRsc = comUtil.getBizSession("CIO", "INQRSC");
        trans.inqRscn = comUtil.getBizSession("CIO", "INQRSCN");
        trans.setServiceID("CIOBP12070"); //서비스ID
        trans.setTransactionID("CIOBP12070R01"); //거래ID : [전계좌조회]
        trans.setDatas(["dataMap1"]); //데이터노드
        trans.setCallbackFnc("mFun.searchInfoCallBack"); //Callback Function
        trans.send();
    };
    mFun.searchInfoCallBack = function(tran) {
        if (!ciobCommon.isError(tran)) {
            if ("0" == tran.div) {
                inqFlag = true;
                dataList1.setJSON(tran.resRecords.LNDEP_ACNT_PS_LIST.nc_list); //전계좌조회 - 여수신 계좌 현황 리스트
                dataList2.setJSON(tran.resRecords.BANCA_CNTRCT_PS_LIST.nc_list); //전계좌조회 - 방카슈랑스 계약 현황 리스트
                dataList15.setJSON(tran.resRecords.FRC_DPO_LIST.nc_list); //전계좌조회 - 외화예금
                grpFrcDpoDiv.hide();
                grpEtcFrcGuarDiv.hide();
                grpNtiLdgDiv.hide();
                grpExptDiv.hide();
                grpNcmDiv.hide();
                grpBuyLoclLcDiv.hide();
                grpOpenLoclLcDiv.hide();
                grpFrcChckDiv.hide();
                checkTab1 = 0;
                checkTab2 = 0;
                dataList3.removeAll();
                dataList4.removeAll();
                dataList5.removeAll();
                dataList6.removeAll();
                dataList7.removeAll();
                dataList8.removeAll();
                dataList9.removeAll();
                dataList10.removeAll();
                dataList11.removeAll();
                dataList12.removeAll();
                dataList13.removeAll();
                dataList14.removeAll();
                if (tran.resRecords.FRC_DPO_LIST.nc_list.length > 0) {
                    grpFrcDpoDiv.show();
                }
                dataList16.setJSON(tran.resRecords.ETC_FRC_GUAR_LIST.nc_list); //전계좌조회 - 기타외화지급보증			
                if (tran.resRecords.ETC_FRC_GUAR_LIST.nc_list.length > 0) {
                    grpEtcFrcGuarDiv.show();
                }
                dataList17.setJSON(tran.resRecords.NTI_LDG_LIST.nc_list); //전계좌조회 - 통지원장
                if (tran.resRecords.NTI_LDG_LIST.nc_list.length > 0) {
                    grpNtiLdgDiv.show();
                }
                dataList18.setJSON(tran.resRecords.EXPT_LIST.nc_list); //전계좌조회 - 수출
                if (tran.resRecords.EXPT_LIST.nc_list.length > 0) {
                    grpExptDiv.show();
                }
                dataList19.setJSON(tran.resRecords.NCM_LIST.nc_list); //전계좌조회 - 수입
                if (tran.resRecords.NCM_LIST.nc_list.length > 0) {
                    grpNcmDiv.show();
                }
                dataList20.setJSON(tran.resRecords.BUY_LOCL_LC_LIST.nc_list); //전계좌조회 - 내국신용장_매입										
                if (tran.resRecords.BUY_LOCL_LC_LIST.nc_list.length > 0) {
                    grpBuyLoclLcDiv.show();
                }
                dataList21.setJSON(tran.resRecords.OPEN_LOCL_LC_LIST.nc_list); //전계좌조회 - 내국신용장_개설
                if (tran.resRecords.OPEN_LOCL_LC_LIST.nc_list.length > 0) {
                    grpOpenLoclLcDiv.show();
                }
                dataList22.setJSON(tran.resRecords.FRC_CHCK_LIST.nc_list); //전계좌조회 - 외화수표
                if (tran.resRecords.FRC_CHCK_LIST.nc_list.length > 0) {
                    grpFrcChckDiv.show();
                }
                dataList23.setJSON(tran.resRecords.LNDEP_ACNT_PS_FML_LIST.nc_list); //전계좌조회 - 가족 고객 여수신 계좌 현황 리스트 
            } else if ("1" == tran.div) {
                dataList3.setJSON(tran.resRecords.DPPD_INFO_LIST.nc_list); //과거거래내역 - 수신 정보 리스트
                dataList4.setJSON(tran.resRecords.LN_INFO_LIST.nc_list); //과거거래내역 - 여신 정보 리스트
                dataList5.setJSON(tran.resRecords.FX_INFO_LIST.nc_list); //과거거래내역 - 외환 정보 리스트
            } else if ("2" == tran.div) {
                dataList6.setJSON(tran.resRecords.LO_AMT_LIST.nc_list); //여신,담보 - 대출금
                dataList7.setJSON(tran.resRecords.IPAY_AMT_LIST.nc_list); //여신,담보 - 대지급금
                dataList8.setJSON(tran.resRecords.GUAR_LIST.nc_list); //여신,담보 - 지급보증
                dataList9.setJSON(tran.resRecords.BUY_FX_LIST.nc_list); //여신,담보 - 매입외환
                dataList10.setJSON(tran.resRecords.LOCL_LC_BUY_LIST.nc_list); //여신,담보 - 내국신용장매입
                dataList11.setJSON(tran.resRecords.HSLF_LO_ATPR_SGRN_LIST.nc_list); //여신,담보 - 본인대출타인입보정보
                dataList12.setJSON(tran.resRecords.HSLF_LO_SGRN_MTG_LIST.nc_list); //여신,담보 - 본인대출입보담보
                dataList13.setJSON(tran.resRecords.ATPR_LO_SGRN_LIST.nc_list); //여신,담보 - 타인대출입보정보
                dataList14.setJSON(tran.resRecords.ATPR_LO_OFR_MTG_LIST.nc_list); //여신,담보 - 타인대출제공담보
            }
        }
    };
    mFun.openReport = function() {
        window.reportDataList1 = dataList1;
        for (var i = 0; i < reportDataList1.getRowCount(); i++) {
